const PRECIO_BASE = 4000;       // hasta KG_INCLUIDOS
const KG_INCLUIDOS = 5;
const TOPE_TRAMO_1 = 20;        // kg donde cambia el precio por kilo
const PESOS_KG_TRAMO_1 = 300;
const PESOS_KG_TRAMO_2 = 450;
const RECARGO_ZONA = { 1: 1.0, 2: 1.35, 3: 1.9 };
const RECARGO_EXPRESS = 1.5;
const AJUSTE_EXPRESS_PESADO = 500; // se resta si el paquete pasa de TOPE_TRAMO_1
const DESCUENTO_CLIENTE = { VIP: 0.1, MAYORISTA: 0.18 };
const PRECIO_MINIMO = 3500;

function precioPorPeso(kg) {
  if (kg <= KG_INCLUIDOS) return PRECIO_BASE;
  const kgTramo1 = Math.min(kg, TOPE_TRAMO_1) - KG_INCLUIDOS;
  const kgTramo2 = Math.max(kg - TOPE_TRAMO_1, 0);
  return PRECIO_BASE + kgTramo1 * PESOS_KG_TRAMO_1 + kgTramo2 * PESOS_KG_TRAMO_2;
}

function aplicarExpress(precio, kg) {
  const conRecargo = precio * RECARGO_EXPRESS;
  return kg > TOPE_TRAMO_1 ? conRecargo - AJUSTE_EXPRESS_PESADO : conRecargo;
}

function aplicarDescuento(precio, cliente) {
  if (!Object.hasOwn(DESCUENTO_CLIENTE, cliente)) return precio;
  return precio - precio * DESCUENTO_CLIENTE[cliente];
}

function presupuestarOrdenado(kg, zona, express, cliente) {
  if (!(kg > 0)) return "peso inválido";
  if (!Object.hasOwn(RECARGO_ZONA, zona)) return "zona inválida";
  const recargoZona = RECARGO_ZONA[zona];

  let precio = precioPorPeso(kg) * recargoZona;
  if (express) precio = aplicarExpress(precio, kg);
  precio = aplicarDescuento(precio, cliente);
  return Math.round(Math.max(precio, PRECIO_MINIMO));
}

